def _getTscFrequencyDmesg():
    """
    Reads TSC Frequency from dmesg log
    """
    tscRe = re.compile('.*tsc:\D*(?P<freq>[.\d]+) MHz.*')
    try:
        with open(DMESG_PATH) as f:
            for line in f:
                m = tscRe.match(line)
                if m is None:
                    continue
                return m.group('freq')
    except:
        logging.warning('Could not read TSC frequency from ' + DMESG_PATH,
                        exc_info=True)
        return ''
